87	bool validate_single_pem(std::string_view content,
88	                         const std::vector<unsigned char>& der) {
89	    enum class State { BeforeMarker, InBody, AfterMarker };
90	    State state = State::BeforeMarker;
91	    std::string base64;
92	    size_t start = 0;
93	    while (true) {
94	        size_t newline = content.find('\n', start);
95	        std::string_view line = content.substr(
96	            start, newline == std::string_view::npos ? std::string_view::npos
97	                                                     : newline - start);
98	        if (!line.empty() && line.back() == '\r') line.remove_suffix(1);
99	        size_t begin = 0;
100	        size_t end = line.size();
101	        while (begin < end &&
102	               std::isspace(static_cast<unsigned char>(line[begin]))) {
103	            ++begin;
104	        }
105	        while (end > begin &&
106	               std::isspace(static_cast<unsigned char>(line[end - 1]))) {
107	            --end;
108	        }
109	        std::string_view trimmed = line.substr(begin, end - begin);
110	
111	        switch (state) {
112	            case State::BeforeMarker:
113	                if (!trimmed.empty()) {
114	                    if (trimmed != kPemBegin) return false;
115	                    state = State::InBody;
116	                }
117	                break;
118	            case State::InBody:
119	                if (trimmed == kPemEnd) {
120	                    state = State::AfterMarker;
121	                } else if (!trimmed.empty()) {
122	                    for (char c : trimmed) {
123	                        if (!is_base64_token(c)) return false;
124	                    }
125	                    base64.append(trimmed);
126	                }
127	                break;
128	            case State::AfterMarker:
129	                if (!trimmed.empty()) return false;
130	                break;
131	        }
132	
133	        if (newline == std::string_view::npos) break;
134	        start = newline + 1;
135	    }
136	    if (state != State::AfterMarker) return false;
137	
138	    std::vector<unsigned char> decoded;
139	    return base64_decode(base64, decoded) && decoded == der;
140	}
