284	    std::string out;
285	    out.reserve(length * 3);
286	    for (size_t i = 0; i < length; ++i) {
287	        char byte_buffer[4];
288	        std::snprintf(byte_buffer, sizeof(byte_buffer), "%02X", digest[i]);
289	        if (i != 0) out.push_back(':');
