295	int inspect_file(const std::string& path) {
296	    std::ifstream stream(path, std::ios::binary);
297	    if (!stream) {
298	        std::cerr << "trustpeek: failed to read file '" << path
299	                  << "': " << std::strerror(errno) << '\n';
300	        return 1;
301	    }
302	    std::ostringstream contents;
303	    contents << stream.rdbuf();
304	    if (stream.bad()) {
305	        std::cerr << "trustpeek: failed to read file '" << path
306	                  << "': " << std::strerror(errno) << '\n';
307	        return 1;
308	    }
309	    std::string content = contents.str();
310	
311	    if (content.empty()) {
312	        std::cerr << "trustpeek: invalid certificate in '" << path
313	                  << "': empty file\n";
314	        return 1;
315	    }
316	
317	    // The encoding is decided by what actually parses, never by the file
318	    // extension and never by marker-like text inside the certificate itself
319	    // (a subject name may legitimately contain "-----BEGIN CERTIFICATE-----").
320	    //
321	    // A DER certificate starts with a SEQUENCE tag (0x30), which no PEM file
322	    // can start with, so the two formats cannot be confused: try DER first
323	    // and require the certificate to occupy the entire file.
324	    const auto* const der_begin =
325	        reinterpret_cast<const unsigned char*>(content.data());
326	    const auto* const der_end = der_begin + content.size();
327	    const unsigned char* pointer = der_begin;
328	
329	    X509Ptr cert(d2i_X509(nullptr, &pointer,
330	                          static_cast<long>(content.size())),
331	                 X509_free);
332	    bool is_pem = false;
333	
334	    if (cert) {
335	        if (pointer != der_end) {
336	            std::cerr << "trustpeek: invalid certificate in '" << path
337	                      << "': trailing bytes after DER certificate\n";
338	            return 1;
339	        }
340	    } else {
341	        BioPtr bio(BIO_new_mem_buf(content.data(),
342	                                  static_cast<int>(content.size())),
343	                   BIO_free_all);
344	        if (!bio) {
345	            std::cerr << "trustpeek: internal error while reading '" << path
346	                      << "'\n";
347	            return 1;
348	        }
349	        cert.reset(PEM_read_bio_X509(bio.get(), nullptr, nullptr, nullptr));
350	        if (!cert) {
351	            // The marker search below only picks the diagnostic wording;
352	            // acceptance is always decided by the parse results above.
353	            if (content.find(kPemBegin) != std::string::npos) {
354	                std::cerr << "trustpeek: invalid certificate in '" << path
355	                          << "': PEM certificate block is malformed or "
356	                             "truncated\n";
357	            } else {
358	                std::cerr << "trustpeek: invalid certificate in '" << path
359	                          << "': DER certificate is malformed or truncated\n";
360	            }
361	            return 1;
362	        }
363	        is_pem = true;
364	    }
365	
366	    std::vector<unsigned char> der;
367	    if (!encode_to_der(cert.get(), der)) {
368	        std::cerr << "trustpeek: invalid certificate in '" << path
369	                  << "': failed to re-encode certificate\n";
370	        return 1;
371	    }
372	
373	    if (is_pem && !validate_single_pem(content, der)) {
374	        std::cerr << "trustpeek: invalid certificate in '" << path
375	                  << "': expected exactly one PEM certificate block with no "
376	                     "other non-whitespace content\n";
377	        return 1;
378	    }
379	
380	    const char* encoding_name = is_pem ? "PEM" : "DER";
381	
382	    std::string subject;
383	    std::string issuer;
384	    std::string not_before;
385	    std::string not_after;
386	    if (!format_name(X509_get_subject_name(cert.get()), subject) ||
387	        !format_name(X509_get_issuer_name(cert.get()), issuer) ||
388	        !format_time(X509_get0_notBefore(cert.get()), not_before) ||
389	        !format_time(X509_get0_notAfter(cert.get()), not_after)) {
390	        std::cerr << "trustpeek: invalid certificate in '" << path
391	                  << "': failed to parse certificate fields\n";
392	        return 1;
393	    }
394	
395	    unsigned char digest[EVP_MAX_MD_SIZE];
396	    size_t digest_length = 0;
397	    if (EVP_Q_digest(nullptr, "SHA256", nullptr, der.data(), der.size(), digest,
398	                     &digest_length) != 1) {
399	        std::cerr << "trustpeek: internal error while hashing '" << path
400	                  << "'\n";
401	        return 1;
402	    }
403	
404	    std::ostringstream output;
405	    output << "Encoding: " << encoding_name << '\n'
406	           << "Subject: " << subject << '\n'
407	           << "Issuer: " << issuer << '\n'
408	           << "Not Before: " << not_before << '\n'
409	           << "Not After: " << not_after << '\n'
410	           << "SHA-256 Fingerprint: "
411	           << format_fingerprint(digest, digest_length) << '\n'
412	           << "Note: this output displays certificate information only; "
413	              "reading the file successfully does not verify the signature "
414	              "or establish trust.\n";
415	    std::cout << output.str();
416	    return 0;
417	}
