#define _GNU_SOURCE
#include <dlfcn.h>
#include <errno.h>
#include <fcntl.h>
#include <string.h>
#include <unistd.h>
#include <stdio.h>

/* When opening the special path, mark the fd. Reads on a marked fd are
   served by the real file until TRIP bytes have been delivered, then fail
   with EIO forever. */
static const char *TARGET = "/tmp/tp/eio_file";
#define TRIP_VAR "EIO_TRIP"
static int marked[256];
static off_t served[256];
static off_t trip_at;

static int mark_if_target(int fd, const char *path) {
    if (fd >= 0 && fd < 256 && path && strcmp(path, TARGET) == 0) {
        const char *t = getenv(TRIP_VAR);
        trip_at = t ? atoll(t) : 0;
        marked[fd] = 1;
        served[fd] = 0;
    }
    return fd;
}

int open(const char *path, int flags, ...) {
    static int (*real_open)(const char*, int, ...) = NULL;
    if (!real_open) real_open = dlsym(RTLD_NEXT, "open");
    return mark_if_target(real_open(path, flags), path);
}
int open64(const char *path, int flags, ...) {
    static int (*real_open64)(const char*, int, ...) = NULL;
    if (!real_open64) real_open64 = dlsym(RTLD_NEXT, "open64");
    return mark_if_target(real_open64(path, flags), path);
}

ssize_t read(int fd, void *buf, size_t count) {
    static ssize_t (*real_read)(int, void*, size_t) = NULL;
    if (!real_read) real_read = dlsym(RTLD_NEXT, "read");
    if (fd >= 0 && fd < 256 && marked[fd]) {
        off_t left = trip_at - served[fd];
        if (left <= 0) { errno = EIO; return -1; }
        if ((off_t)count > left) count = (size_t)left;
        ssize_t n = real_read(fd, buf, count);
        if (n > 0) served[fd] += n;
        return n;
    }
    return real_read(fd, buf, count);
}

int close(int fd) {
    static int (*real_close)(int) = NULL;
    if (!real_close) real_close = dlsym(RTLD_NEXT, "close");
    if (fd >= 0 && fd < 256) marked[fd] = 0;
    return real_close(fd);
}
